package com.guardianlab.chat
import android.Manifest
import android.app.*
import android.content.Intent
import android.content.pm.PackageManager
import android.media.AudioAttributes
import android.media.RingtoneManager
import android.os.Build
import com.google.firebase.messaging.FirebaseMessagingService
import com.google.firebase.messaging.RemoteMessage
class CallPushService:FirebaseMessagingService(){
 override fun onNewToken(token:String){PushRegistration.sync(this,token)}
 override fun onMessageReceived(message:RemoteMessage){android.util.Log.i("GuardianCallPush","Received call push");val data=message.data;if(data["event"]=="chat_message"){MessageNotifications.receive(this,data);return};if(data["event"]=="market_notice"){marketNotice(data);return};if(data["event"]=="gamebox_notice"){gameboxNotice(data);return};val id=data["call_id"]?:return;if(!id.matches(Regex("[a-f0-9]{32}")))return;val prefs=getSharedPreferences("account",MODE_PRIVATE);if(data["recipient"]!=prefs.getString("id",""))return;val manager=getSystemService(NotificationManager::class.java);val state=getSharedPreferences("push_state",MODE_PRIVATE);if(data["event"]=="call_cancelled"){state.edit().putString("cancelled",id).putLong("cancelled_at",System.currentTimeMillis()).apply();if(state.getString("ringing","")==id)manager.cancel(880001);return};if(data["event"]!="call_ringing"||!prefs.getBoolean("incomingCalls",true)||MainActivity.appVisible)return;val expires=data["expires_at"]?.toLongOrNull()?:return;if(expires<=System.currentTimeMillis()/1000)return;if(state.getString("cancelled","")==id&&System.currentTimeMillis()-state.getLong("cancelled_at",0)<60000)return;if(Build.VERSION.SDK_INT>=33&&checkSelfPermission(Manifest.permission.POST_NOTIFICATIONS)!=PackageManager.PERMISSION_GRANTED)return;val token=prefs.getString("token","")?:return;if(token.isEmpty())return;var call:org.json.JSONObject?=null;try{val calls=ChatApi(prefs.getString("server","")!!,token).request("/calls",timeoutMillis=3500).getJSONArray("calls");for(i in 0 until calls.length()){val c=calls.getJSONObject(i);if(c.optString("id")==id&&c.optString("recipient")==prefs.getString("id","")&&c.optString("state")=="ringing")call=c};if(call==null){android.util.Log.i("GuardianCallPush","No matching ringing call");return}}catch(e:Exception){android.util.Log.w("GuardianCallPush","Call verification failed: "+e.javaClass.simpleName);return};val c=call?:return;val channel=NotificationChannel("incoming_calls","Incoming calls",NotificationManager.IMPORTANCE_HIGH).apply {setSound(RingtoneManager.getDefaultUri(RingtoneManager.TYPE_RINGTONE),AudioAttributes.Builder().setUsage(AudioAttributes.USAGE_NOTIFICATION_RINGTONE).setContentType(AudioAttributes.CONTENT_TYPE_SONIFICATION).build());enableVibration(true)};manager.createNotificationChannel(channel);val open=Intent(this,MainActivity::class.java).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK or Intent.FLAG_ACTIVITY_CLEAR_TOP or Intent.FLAG_ACTIVITY_SINGLE_TOP).putExtra("incomingCallId",id);val tap=PendingIntent.getActivity(this,880001,open,PendingIntent.FLAG_UPDATE_CURRENT or PendingIntent.FLAG_IMMUTABLE);val reject=PendingIntent.getBroadcast(this,880002,Intent(this,CallActionsReceiver::class.java).putExtra("callId",id),PendingIntent.FLAG_UPDATE_CURRENT or PendingIntent.FLAG_IMMUTABLE);val remaining=(expires-System.currentTimeMillis()/1000).coerceIn(1,45)*1000;val builder=Notification.Builder(this,"incoming_calls").setSmallIcon(R.drawable.ic_call_incoming).setContentTitle(if(c.optString("kind")=="video")"Incoming video call"else "Incoming audio call").setContentText(c.optString("peer_name","Contact")).setCategory(Notification.CATEGORY_CALL).setVisibility(Notification.VISIBILITY_PRIVATE).setContentIntent(tap).setTimeoutAfter(remaining).setOngoing(true).setFullScreenIntent(tap,true);if(Build.VERSION.SDK_INT>=31){builder.setStyle(Notification.CallStyle.forIncomingCall(Person.Builder().setName(c.optString("peer_name","Contact")).setImportant(true).build(),reject,tap).setIsVideo(c.optString("kind")=="video"))}else{builder.addAction(Notification.Action.Builder(R.drawable.ic_call_incoming,"Open call",tap).build()).addAction(Notification.Action.Builder(R.drawable.ic_call_missed,"Decline",reject).build())};val n=builder.build();n.flags=n.flags or Notification.FLAG_INSISTENT;state.edit().putString("ringing",id).apply();manager.notify(880001,n);android.util.Log.i("GuardianCallPush","Incoming call notification posted")}
 private fun gameboxNotice(data:Map<String,String>){val prefs=getSharedPreferences("account",MODE_PRIVATE);if(data["recipient"]!=prefs.getString("id","")||!prefs.getBoolean("gameboxAlerts",true))return;val expires=data["expires_at"]?.toLongOrNull()?:return;if(expires<=System.currentTimeMillis()/1000)return;if(Build.VERSION.SDK_INT>=33&&checkSelfPermission(Manifest.permission.POST_NOTIFICATIONS)!=PackageManager.PERMISSION_GRANTED)return;val id=data["notice_id"]?.toIntOrNull()?:return;val token=prefs.getString("token","")?:return;if(token.isEmpty())return;try{val notices=ChatApi(prefs.getString("server","")!!,token).request("/gamebox/summary",timeoutMillis=4000).getJSONArray("notices");var found=false;for(i in 0 until notices.length())if(notices.getJSONObject(i).optInt("id")==id)found=true;if(!found)return}catch(_:Exception){return};val manager=getSystemService(NotificationManager::class.java);manager.createNotificationChannel(NotificationChannel("gamebox_updates","Gamebox match updates",NotificationManager.IMPORTANCE_DEFAULT));val open=Intent(this,MainActivity::class.java).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK or Intent.FLAG_ACTIVITY_CLEAR_TOP or Intent.FLAG_ACTIVITY_SINGLE_TOP).putExtra("gameboxNotice",true).putExtra("gameboxNoticeId",id);val tap=PendingIntent.getActivity(this,id,open,PendingIntent.FLAG_UPDATE_CURRENT or PendingIntent.FLAG_IMMUTABLE);manager.notify(900000+id,Notification.Builder(this,"gamebox_updates").setSmallIcon(android.R.drawable.ic_dialog_info).setContentTitle("Gamebox match update").setContentText("Open Gamebox to view your match update.").setVisibility(Notification.VISIBILITY_PRIVATE).setContentIntent(tap).setAutoCancel(true).build())}

 private fun marketNotice(data:Map<String,String>){val prefs=getSharedPreferences("account",MODE_PRIVATE);val account=prefs.getString("id","")?:return;if(data["recipient"]!=account||!prefs.getBoolean("notifications",false)||!prefs.getBoolean("marketAlerts",true))return;val expires=data["expires_at"]?.toLongOrNull()?:return;if(expires<=System.currentTimeMillis()/1000)return;if(Build.VERSION.SDK_INT>=33&&checkSelfPermission(Manifest.permission.POST_NOTIFICATIONS)!=PackageManager.PERMISSION_GRANTED)return;val id=data["notice_id"]?.toIntOrNull()?.takeIf {it>0}?:return;val token=prefs.getString("token","")?:return;if(token.isEmpty())return;val notice=try{ChatApi(prefs.getString("server","")!!,token).request("/market/activity_item?id=$id",timeoutMillis=4000).getJSONObject("notification")}catch(_:Exception){return};if(notice.optInt("seen")!=0||prefs.getString("token","")!=token)return;val manager=getSystemService(NotificationManager::class.java);manager.createNotificationChannel(NotificationChannel("market_updates","OrbitPlaza updates",NotificationManager.IMPORTANCE_DEFAULT));val open=Intent(this,MainActivity::class.java).setData(android.net.Uri.parse("xorbit://market/$account/notice/$id")).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK or Intent.FLAG_ACTIVITY_CLEAR_TOP or Intent.FLAG_ACTIVITY_SINGLE_TOP).putExtra("marketNoticeId",id).putExtra("notificationAccount",account);val tap=PendingIntent.getActivity(this,id,open,PendingIntent.FLAG_UPDATE_CURRENT or PendingIntent.FLAG_IMMUTABLE);manager.notify("market",id,Notification.Builder(this,"market_updates").setOnlyAlertOnce(true).setSmallIcon(android.R.drawable.ic_dialog_info).setContentTitle("OrbitPlaza").setContentText(notice.getString("text")).setStyle(Notification.BigTextStyle().bigText(notice.getString("text"))).setVisibility(Notification.VISIBILITY_PRIVATE).setContentIntent(tap).setAutoCancel(true).build())}

}
